// Ingest every agent that has a knowledge base.
// The ingest is idempotent, so running it on a schedule is cheap.
const base = $env.CONDUIT_CREW_URL || 'http://127.0.0.1:8787';
const key = $env.AGENTIC_CREW_API_KEY;

const agents = $input.first().json;
const results = [];

for (const agent of agents) {
  if (!agent.name) continue;
  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: `${base}/agents/${encodeURIComponent(agent.name)}/ingest`,
      headers: { 'Content-Type': 'application/json', ...(key ? { Authorization: `Bearer ${key}` } : {}) },
      body: { force: false },
      json: true,
    });
    results.push({ agent: agent.name, ok: true, chunks: response.chunks, errors: response.errors });
  } catch (error) {
    results.push({ agent: agent.name, ok: false, error: error.message });
  }
}

return results.map((item) => ({ json: item }));
